import java.util.List;

/**
 * A policy the MHPCO has issued over a list of insured items: what the office
 * covers, and what the covered items are insured for.
 *
 * How far beyond the insurance sum the office will pay out is a separate
 * decision, made by {@link PayoutCap}.
 */
public final class Policy {

    private final List<Item> insuredItems;

    public Policy(List<Item> insuredItems) {
        this.insuredItems = List.copyOf(insuredItems);
    }

    /**
     * What the covered items are insured for, all together: each item at its
     * own insurance value, summed. What the MHPCO charged to insure them does
     * not enter into it -- neither a risk surcharge nor the component block
     * offer moves the insurance sum.
     */
    public int insuranceSum() {
        return insuredItems.stream()
                .mapToInt(InsuranceValues::insuranceValueOf)
                .sum();
    }

    /**
     * The most the MHPCO will pay out over the life of this policy. No claim
     * has yet been made against a policy, so this is the whole cap; what
     * remains of it after claims is a claim's concern.
     */
    public int cap() {
        return PayoutCap.overInsuranceSum(insuranceSum());
    }

    /**
     * The MHPCO settles an incident against this policy: it reimburses the
     * incident and reports what the settlement leaves of the policy's cap.
     */
    public Claim claim(Incident incident) {
        int payout = Reimbursement.forIncident(incident, this::damagedItem);
        return new Claim(payout, cap() - payout);
    }

    /**
     * The insured item a reported damage was suffered by, found among the
     * items this policy covers.
     */
    private Item damagedItem(Damage damage) {
        return insuredItems.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }
}
