import java.util.function.Function;

/**
 * What the MHPCO reimburses for reported damage: the amount it reimburses for
 * the damage, less the deductible that applies per damage event.
 *
 * This is the one place that says how much an incident is worth to the
 * claimant. How far the MHPCO will actually go in paying that -- what the
 * policy's cap leaves of it -- is a separate decision, made where the policy
 * settles the claim.
 */
public final class Reimbursement {

    private static final int DEDUCTIBLE_PER_DAMAGE_IN_G = 100;

    private static final int HIGH_ENCHANTMENT_LEVEL = 8;

    private static final int HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;

    private Reimbursement() {
    }

    /**
     * An incident is reimbursed damage by damage: the office settles each
     * reported damage on its own and pays the sum, because the deductible is
     * charged per damage event rather than once for the incident.
     */
    public static int forIncident(Incident incident, Function<Damage, Item> damagedItem) {
        return incident.damages().stream()
                .mapToInt(damage -> forDamage(damage, damagedItem.apply(damage)))
                .sum();
    }

    /**
     * One reported damage is settled in two steps the MHPCO decides
     * separately: how much of the damage it reimburses at all, and then the
     * deductible it charges for the damage event.
     */
    private static int forDamage(Damage damage, Item damagedItem) {
        return reimbursableAmount(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE_IN_G;
    }

    /**
     * How much of a reported damage the MHPCO reimburses, before the
     * deductible: damage to a highly enchanted item is reimbursed at half,
     * anything else in full.
     */
    private static int reimbursableAmount(Damage damage, Item damagedItem) {
        if (isHighlyEnchanted(damagedItem)) {
            return Percentage.of(damage.amount(), HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
                    .intValueExact();
        }
        return damage.amount();
    }

    /**
     * The MHPCO only reimburses damage to an item of enchantment level 8 or
     * more at half: such items are too volatile to insure in full.
     */
    private static boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    }
}
===== InsurableItems.java =====
import java.util.List;

/**
 * The item types the MHPCO insures at all: the main items of its price list
 * and the components it offers. An item of any other type cannot be covered,
 * and the MHPCO declines the whole request rather than quoting around it.
 *
 * This is the one place that decides what the office will take on. What an
 * accepted item is insured for is a separate decision, made by
 * {@link InsuranceValues}.
 */
public final class InsurableItems {

    private InsurableItems() {
    }

    public static boolean isInsurable(String itemType) {
        return MainItemPricing.isMainItem(itemType) || ComponentPricing.isComponent(itemType);
    }

    public static void requireAllInsurable(List<Item> items) {
        items.stream()
                .map(Item::type)
                .filter(itemType -> !isInsurable(itemType))
                .findFirst()
                .ifPresent(itemType -> {
                    throw new IllegalArgumentException(
                            "The MHPCO does not insure items of type " + itemType);
                });
    }
}
===== InsuranceValues.java =====
/**
 * What the MHPCO insures an item for. Each family of insurable item is valued
 * by the pricing policy that owns it: a main item by the price list, a
 * component by the flat component value.
 *
 * This is the one place that decides which valuation an item falls under. It
 * is a separate decision from whether the MHPCO will cover the item at all:
 * the office may take on a new kind of item without changing what the items it
 * already covers are worth, and may revalue what it covers without widening
 * what it accepts.
 */
public final class InsuranceValues {

    private InsuranceValues() {
    }

    public static int insuranceValueOf(Item item) {
        if (ComponentPricing.isComponent(item.type())) {
            return ComponentPricing.componentInsuranceValue(item);
        }
        return MainItemPricing.mainItemInsuranceValue(item);
    }
}

